class DH_Parameters:
    def __init__(self, m: int, g: int, q: int, p: int):
        self.modulus_size = m
        self.g = g
        self.p = p
        self.q = q

class DH_Private_Key:
    def __init__(self, parameters: DH_Parameters):
        self.parameters = parameters

        #5.6.1.1.3 (implement algorithm)
        #1, 2, and 3
        N = math.floor((self.parameters.q.bit_length() + 64) / 8) # converted to bytes 
        c_bytestr = urandom(N)
        c = int.from_bytes(c_bytestr, byteorder="big")
        M = min(2**N, q)
        self.x = (c % (M - 1)) + 1
        self.public_key = DH_Public_Key(parameters, self.x)

class DH_Public_Key:
    def __init__(self, parameters: DH_Parameters, x: int):
        self.parameters = parameters
        self.y = pow(self.parameters.g, x, self.parameters.p)
    

