class DH:
    def __init__(self, modulus: int):
        self.private_key = self.generatePrivateKey(modulus)
        self.public_key = self.generatePublicKey(self.private_key)
    
    def generatePrivateKey(self, modulus: int):
        parameters = next((safe for safe in safe_primes if safe.modulus_size == modulus), None)
        if (parameters is None):
            raise ValueError("modulus must be a safe prime")
        return DH_Private_Key(parameters)

    def generatePublicKey(self, privateKey: DH_Private_Key):
        return privateKey.public_key

    def generateSharedSecret(self, otherPublicKey: DH_Public_Key):
        Z = pow(otherPublicKey.y, self.private_key.x, self.private_key.parameters.p)
        t = math.ceil(math.log2(self.private_key.parameters.p))
        n = math.ceil(t / 8)
        return Z.to_bytes(n, byteorder="big")




